import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { 
  Book, 
  Users, 
  CheckSquare, 
  Award, 
  Plus, 
  Calendar 
} from 'lucide-react';
import Layout from '../common/Layout';

const ProfessorDashboard = () => {
  const { currentUser } = useAuth();
  const [stats, setStats] = useState({
    totalQuizzes: 0,
    activeQuizzes: 0,
    totalStudents: 0,
    completedSessions: 0
  });
  
  const [recentQuizzes, setRecentQuizzes] = useState([]);
  const [loading, setLoading] = useState(true);
  
  useEffect(() => {
    setTimeout(() => {
      setStats({
        totalQuizzes: 12,
        activeQuizzes: 5,
        totalStudents: 78,
        completedSessions: 243
      });
      
      setRecentQuizzes([
        {
          id: 'q1',
          title: 'Introduction à JavaScript',
          createdAt: '2025-04-25',
          status: 'active',
          attempts: 23,
          avgScore: 78
        },
        {
          id: 'q2',
          title: 'Les bases de React',
          createdAt: '2025-04-20',
          status: 'active',
          attempts: 18,
          avgScore: 65
        },
        {
          id: 'q3',
          title: 'CSS Avancé',
          createdAt: '2025-04-15',
          status: 'inactive',
          attempts: 25,
          avgScore: 72
        }
      ]);
      
      setLoading(false);
    }, 800);
  }, []);
  
  return (
    <Layout title="Tableau de Bord" userRole="professor">
      <div className="dashboard-container w-full h-full px-6 py-4"> {/* Ajout de w-full et h-full */}
        <h2 className="welcome-message text-2xl font-bold mb-6">Bienvenue, {currentUser?.name || 'Professeur'}!</h2>
        
        {loading ? (
          <div className="loading text-center">Chargement des données...</div>
        ) : (
          <>
            {/* Cartes de statistiques */}
            <div className="dashboard-cards grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
              {[
                { title: 'Total Quiz', icon: <Book size={20} color="#2ac3a2" />, value: stats.totalQuizzes },
                { title: 'Quiz Actifs', icon: <CheckSquare size={20} color="#4285f4" />, value: stats.activeQuizzes },
                { title: 'Étudiants', icon: <Users size={20} color="#ea4335" />, value: stats.totalStudents },
                { title: 'Sessions Complétées', icon: <Award size={20} color="#fbbc05" />, value: stats.completedSessions }
              ].map((card, idx) => (
                <div className="card bg-white rounded-lg shadow p-6" key={idx}>
                  <div className="card-header flex justify-between items-center mb-4">
                    <h3 className="text-sm font-medium text-gray-500">{card.title}</h3>
                    {card.icon}
                  </div>
                  <div className="card-content">
                    <p className="text-2xl font-semibold">{card.value}</p>
                  </div>
                </div>
              ))}
            </div>
            
            {/* Section des quiz récents */}
            <section className="recent-activity">
              <div className="section-header flex justify-between items-center mb-4">
                <h2 className="text-lg font-bold">Quiz Récents</h2>
                <Link to="/professor/create-quiz" className="btn btn-primary flex items-center gap-2">
                  <Plus size={16} />
                  Créer un Quiz
                </Link>
              </div>
              
              <div className="table-container overflow-x-auto bg-white rounded-lg shadow p-4">
                <table className="table-auto w-full">
                  <thead>
                    <tr className="bg-gray-50">
                      <th className="px-4 py-2 text-left text-sm font-medium text-gray-500">Titre</th>
                      <th className="px-4 py-2 text-left text-sm font-medium text-gray-500">Date</th>
                      <th className="px-4 py-2 text-left text-sm font-medium text-gray-500">Statut</th>
                      <th className="px-4 py-2 text-left text-sm font-medium text-gray-500">Tentatives</th>
                      <th className="px-4 py-2 text-left text-sm font-medium text-gray-500">Score Moyen</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentQuizzes.map(quiz => (
                      <tr key={quiz.id} className="border-b">
                        <td className="px-4 py-2">{quiz.title}</td>
                        <td className="px-4 py-2">
                          <Calendar size={14} className="inline-block mr-2 text-gray-400" />
                          {quiz.createdAt}
                        </td>
                        <td className="px-4 py-2">
                          <span className={`status-badge ${quiz.status}`}>
                            {quiz.status === 'active' ? 'Actif' : 'Inactif'}
                          </span>
                        </td>
                        <td className="px-4 py-2">{quiz.attempts}</td>
                        <td className="px-4 py-2">
                          <div className="flex items-center">
                            <div
                              className="h-2 rounded-full"
                              style={{
                                width: `${quiz.avgScore}%`,
                                backgroundColor: quiz.avgScore > 70 ? '#34a853' : quiz.avgScore > 50 ? '#fbbc05' : '#ea4335'
                              }}
                            ></div>
                            <span className="ml-2">{quiz.avgScore}%</span>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
            
            {/* Actions rapides */}
            <section className="quick-actions mt-8">
              <h2 className="text-lg font-bold mb-4">Actions Rapides</h2>
              <div className="action-buttons flex gap-4">
                <Link to="/professor/create-quiz" className="btn btn-primary">Créer un Quiz</Link>
                <Link to="/professor/manage-quiz" className="btn btn-secondary">Gérer les Quiz</Link>
                <Link to="/professor/results" className="btn btn-secondary">Voir les Résultats</Link>
              </div>
            </section>
          </>
        )}
      </div>
    </Layout>
  );
};

export default ProfessorDashboard;
